INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-08-05' FROM countries WHERE name_en = 'Costa Rica';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'en', 'Real-time clearance via DGT''s Recepción de Comprobantes Electrónicos service -- mandatory for essentially all VAT taxpayers since 2018, and now mid-transition through Hacienda''s new TRIBU-CR platform', 'This deep-dive page reflects publicly available Hacienda/DGT guidance and industry reporting as of early August 2026 and is provided for general awareness, not legal or tax advice. Confirm current requirements directly with Hacienda, DGT, or a Costa Rican tax adviser before relying on this page for compliance decisions.', 'Costa Rica''s e-invoicing regime traces back to a 2007 first regulation and a 2013 voluntary pilot, became mandatory for healthcare and other professional sectors in early 2018, and completed a general, ID-digit-staggered rollout under Resolution DGT-R-012-2018 by 1 November 2018. Since then, Hacienda has kept evolving the system: XML schema v4.4 became mandatory in September 2025, the TRIBU-CR platform replaced ATV in October 2025, and a further ID-format cutover is expected in November 2026.', 'A compliant invoice is generated as a digitally signed XML document and submitted to DGT''s Recepción de Comprobantes Electrónicos API. DGT validates the document''s structure, fields, and cross-references -- typically near-instant in practice, with a contractual maximum of 3 hours -- and returns an accepted or rejected status before the document is delivered to the recipient. This is a genuine clearance model: an invoice DGT hasn''t accepted has no legal effect.', 'The mandate has been in place in some form since 2007, reached essentially all VAT taxpayers by November 2018, and continues to evolve technically rather than expanding in scope -- the current wave of change (schema v4.4, the TRIBU-CR platform, the upcoming ID-format cutover) is about how compliant businesses transmit and format their invoices, not about who has to comply.', 'Most businesses reading this are likely already required to issue electronic Comprobantes -- the real, current work is keeping pace with Hacienda''s ongoing technical transition (schema v4.4, TRIBU-CR, the 2026 ID-format cutover), not a first-time rollout.', 'Costa Rica backs its e-invoicing mandate with real, article-specific penalties under the Código de Normas y Procedimientos Tributarios (CNPT) -- pegged to Costa Rica''s judicially-set base salary rather than fixed colón amounts -- and DGT has demonstrated it will actually enforce them: a single 2024 sweep fined 279 businesses over ₡253 million.', 'Costa Rica requires real-time DGT clearance of electronic Comprobantes (invoices, tickets, credit/debit notes, and more) for essentially all VAT-registered businesses, mandatory since 2018. The system is currently mid-transition: XML schema v4.4 became mandatory in September 2025, Hacienda''s new TRIBU-CR platform replaced ATV in October 2025, and a further alphanumeric taxpayer-ID cutover is expected in November 2026.', '🇨🇷' FROM countries WHERE name_en = 'Costa Rica';
