INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '₡253M+', 'Fined across 279 taxpayers in a single 2024 DGT enforcement sweep');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Costa Rica';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '≤3 hrs', 'DGT''s maximum response-time SLA for invoice validation');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Costa Rica';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & validation', '[["Invoice format", "Signed XML, Costa Rica''s own schema (not UBL/PEPPOL)"], ["Validation model", "Clearance -- DGT must accept the document before it''s fiscally valid"], ["Submission", "POST to DGT''s Recepción de Comprobantes Electrónicos API (OIDC/OAuth 2.0, base64-encoded XML)"], ["Response time", "Typically near-instant in practice; DGT''s own technical resolution sets a maximum of 3 hours"], ["Digital signature", "XAdES EPES v1.3.2 or higher, using a .p12 certificate issued by the Central Bank''s (BCCR) certification authority"]]', 'Vendor marketing sometimes describes this as pure "real-time" validation -- that''s usually accurate in practice, but the binding SLA in DGT''s own technical resolution is a 3-hour maximum, not an instant guarantee.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Costa Rica';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Document types', '[["01 — Factura Electrónica", "Standard B2B / identified-buyer sale"], ["02 / 03 — Nota de Débito / Crédito", "Adjustments, returns, discounts, cancellations"], ["04 — Tiquete Electrónico", "Retail sale to an unidentified end consumer (B2C)"], ["08 — Factura Electrónica de Compra", "Buyer-issued voucher when purchasing from an informal, non-emitting supplier"], ["09 — Factura Electrónica de Exportación", "Export sales at 0% VAT"]]', 'A Recibo Electrónico de Pago (payment receipt) was added as a further document type with schema v4.4 -- confirm your software issues it where required rather than assuming the five core types above are the complete list.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Costa Rica';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Clave numérica, buyer response & retention', '[["Clave numérica", "A 50-digit key, auto-generated by the issuer''s system, encoding the issue date, issuer ID, document type, consecutive number, and a security code"], ["Buyer response (B2B)", "Recipient must accept, partially accept, or reject within 8 business days of the following month"], ["Contingency mode", "Vouchers may be submitted up to 48 hours after service restoration if Hacienda''s systems are down"], ["Retention", "5 years"]]', 'The exact digit-by-digit layout of the 50-digit clave numérica varies slightly across secondary sources -- treat the total length (50 digits) and general contents as reliable, but don''t rely on a specific position-by-position breakdown without confirming it against Hacienda''s current technical annex.', NULL);
INSERT INTO deep_dive_lifecycle_cards (country_id, section, sort_order, display_style) SELECT id, 'scope_transmission', 0, 'pills' FROM countries WHERE name_en = 'Costa Rica';
INSERT INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 'en', 'The clearance flow', 'A compliant Comprobante Electrónico moves through this sequence:', 'Only an aceptado document is a valid tax voucher -- an invoice DGT hasn''t accepted has no legal effect, and one the recipient properly rejects doesn''t support their deduction.');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 0, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Issuer generates a digitally signed XML using an approved certificate');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 1, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Document submitted to DGT''s Recepción de Comprobantes Electrónicos API');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 2, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'DGT validates structure, fields, and cross-references (near-instant in practice; up to 3 hours contractually)');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 3, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'DGT returns an aceptado or rechazado status');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 4, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Accepted document delivered to the recipient, who must respond within 8 business days of the following month');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Costa Rica';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'What''s required by law', '[["DGT-R-012-2018 (2018)", "The general mandate, staggered by the last digit of the taxpayer ID"], ["Ley 7092 (Income Tax Law), Art. 3", "Legal basis for the narrow public-sector/non-profit exemption"], ["Régimen Simplificado", "Excluded outright from the general mandate"], ["No revenue threshold", "The mandate is universal for VAT-registered taxpayers outside the listed carve-outs"]]', 'B2B, B2C (via Tiquete Electrónico), and B2G transactions are all covered once a taxpayer is in scope -- this isn''t a B2G-only or B2B-only regime.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Costa Rica';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Who''s still excluded', '[["Régimen Simplificado contributors", "Excluded outright under DGT-R-012-2018"], ["Public-sector/non-profit bodies", "For non-commercial activity only -- municipalities, ministries, public universities, CCSS, Central Bank, Judiciary, Legislative Assembly"], ["Professional colleges (colegios profesionales)", "For membership-fee collection only"], ["Condominiums", "For common-area maintenance fees only"], ["SUGEF-regulated banks/cooperatives and solidarist associations", "For specific non-taxed activity only"]]', 'Any commercial or VATable income earned by these same entities still requires e-invoicing -- the exemption is activity-specific, not a blanket carve-out for the organization.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Costa Rica';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚠️ Failing to issue or deliver an invoice carries the sharpest fine', NULL, NULL, 'Under CNPT (Código de Normas y Procedimientos Tributarios) Article 85, failing to issue or deliver an electronic invoice or voucher draws a fine of 2 base salaries -- roughly ₡924,400 at 2024-2025 base-salary values -- with no self-correction discount available for this specific infraction. Costa Rican tax fines of this kind are pegged to the judicially-set "salario base" reference figure rather than a fixed colón amount, so the exact amount moves with the annually-updated base salary.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Costa Rica';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '💳 Refusing electronic or alternative payment has its own penalty', NULL, NULL, 'CNPT Article 85 bis separately penalizes refusing to accept electronic or alternative payment methods (such as card payments or SINPE) when required, with a fine of 1 base salary -- roughly ₡462,200 at 2024-2025 values. This is a distinct infraction from failing to issue the invoice itself, and both can apply to the same business in the same enforcement action.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Costa Rica';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🔁 Repeat violations can mean business closure', NULL, NULL, 'CNPT Article 86 provides for temporary business closure -- reported at 5 days -- on a documented repeat violation after a prior firm resolution. This escalation path means a second confirmed infraction carries a materially different consequence than a first one, not just a larger fine.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 3 FROM countries WHERE name_en = 'Costa Rica';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📰 A real enforcement sweep shows these aren''t theoretical', NULL, NULL, 'In June 2024, DGT visited nearly 1,000 businesses nationwide -- restaurants, sodas, bars, juice vendors, food wholesalers, liquor stores, bookstores, bazaars, and jewelers -- and imposed fines totaling over ₡253 million on 279 taxpayers, citing Article 85 as the legal basis. The exact statutory text of Articles 85, 85 bis, and 86 is well-corroborated across independent sources including this enforcement report, but wasn''t independently pulled from Costa Rica''s official legal database (pgrweb.go.cr) in this round of research -- treat the article numbers and mechanism as reliable, and confirm exact current figures with a Costa Rican tax adviser before relying on them for a specific compliance decision.');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Costa Rica';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Failure to issue or deliver an electronic invoice/voucher (CNPT Art. 85)', '2 base salaries (approximately ₡924,400 at 2024–2025 values); no self-correction discount applies', '—');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Costa Rica';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Refusing to accept electronic or alternative payment methods when required (CNPT Art. 85 bis)', '1 base salary (approximately ₡462,200 at 2024–2025 values)', '—');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Costa Rica';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Repeat/reincidence violation after a prior firm resolution (CNPT Art. 86)', 'Temporary business closure, reported at 5 days', '—');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Costa Rica';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your taxpayer ID digit and which 2018 wave applied to you', 'Costa Rica''s general mandate was staggered by the last digit of your taxpayer ID between September and November 2018 -- confirm your business has been compliant since its wave, not just aware of the mandate in general.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Costa Rica';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Register with a certified e-invoicing solution or Hacienda''s free TICO FACTURA tool', 'Small taxpayers can use Hacienda''s own free tool; larger or higher-volume businesses typically use a certified third-party provider integrated into their accounting system.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Costa Rica';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your systems are certified against XML schema v4.4', 'Schema v4.4 became mandatory 1 September 2025 -- confirm your software or provider has actually implemented the new fields (SINPE Móvil, non-domiciled taxpayer data, exoneration documentation) rather than just passing basic validation.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Costa Rica';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Build the buyer-response workflow into your accounts-payable process', 'As a recipient of B2B invoices, you must accept, partially accept, or reject each one within 8 business days of the following month -- missing this window can create disputes over deductibility.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Costa Rica';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Migrate any remaining ATV-based processes to TRIBU-CR', 'ATV was retired the evening before TRIBU-CR launched on 6 October 2025 -- confirm your team is working entirely in the new platform and TICO FACTURA rather than referencing outdated ATV workflows.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE name_en = 'Costa Rica';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Prepare your systems now for the alphanumeric cédula jurídica format', 'Newly registered companies will carry IDs like 3-101-A00001 rather than the current all-numeric format -- confirm your invoicing and counterparty-validation logic doesn''t hard-code a numeric-only pattern ahead of the expected 1 November 2026 production cutover.');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://www.hacienda.go.cr/docs/ComprobantesElectronicosAPI.html', 0 FROM countries WHERE name_en = 'Costa Rica';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'Ministerio de Hacienda — Comprobantes Electrónicos API, the official technical reference for invoice submission and validation');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://www.hacienda.go.cr/AvisosTRIBU-CR.html', 1 FROM countries WHERE name_en = 'Costa Rica';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'Ministerio de Hacienda — Avisos TRIBU-CR, the official portal for the new integrated tax platform and e-invoicing tools');
